SELECT 'test-pattern-part-three', 'Test pattern: part three', 'A post that exists only in the test database.', 'Fashion law', '["Test tag"]', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fashion has always borrowed. The question is when borrowing becomes taking."}]}, {"type": "marginNote", "attrs": {"kind": "note"}, "content": [{"type": "text", "text": "the whole question, really"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why the existing tools fall short"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Copyright protects original works by identifiable authors for a limited term."}]}, {"type": "marginNote", "attrs": {"kind": "note"}, "content": [{"type": "text", "text": "See the Swakopmund Protocol (2010) on TCEs"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A pattern can belong to a people long before it belongs to a label."}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Where the practical work is happening"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Community protocols and fair attribution clauses."}]}, {"type": "marginNote", "attrs": {"kind": "note"}, "content": [{"type": "text", "text": "more on attribution clauses later"}]}]}', 'Fashion has always borrowed. The question is when borrowing becomes taking. the whole question, really Why the existing tools fall short Copyright protects original works by identifiable authors for a limited term. See the Swakopmund Protocol (2010) on TCEs A pattern can belong to a people long before it belongs to a label. Where the practical work is happening Community protocols and fair attribution clauses. more on attribution clauses later', 70, 'published', '2026-09-01T06:00:00Z', id, 3 FROM series WHERE name = 'Test pattern set'
ON CONFLICT (slug) DO NOTHING;
